===LEGAL.CSS===
:root {
  --orange: #ff6b35;
  --orange-dark: #e4551f;
  --ink: #1e1b18;
  --muted: #6b655f;
  --bg: #fffdfb;
  --tint: #fff3ed;
  --line: #f0e9e3;
  --card: #ffffff;
  --shadow: 0 12px 40px rgba(30, 27, 24, 0.08);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--orange-dark); }
a:hover { color: var(--ink); }

header {
  border-bottom: 1px solid var(--line);
  background: rgba(255, 253, 251, 0.92);
  backdrop-filter: saturate(180%) blur(12px);
}

.nav, .page, .footer-inner {
  width: min(100% - 40px, 820px);
  margin: 0 auto;
}

.nav {
  min-height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.brand {
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 18px;
  font-weight: 800;
  text-decoration: none;
}

.logo {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--orange), #ff9138);
  box-shadow: 0 4px 16px rgba(30, 27, 24, 0.08);
}

.back {
  color: var(--muted);
  font-size: 14px;
  font-weight: 650;
  text-decoration: none;
}

.page { padding: 68px 0 88px; }

.eyebrow {
  color: var(--orange-dark);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
}

h1 {
  margin: 8px 0 12px;
  font-size: clamp(36px, 7vw, 54px);
  line-height: 1.08;
  letter-spacing: -.035em;
}

.intro {
  max-width: 680px;
  margin: 0 0 36px;
  color: var(--muted);
  font-size: 18px;
}

.updated {
  display: inline-block;
  margin-bottom: 36px;
  padding: 7px 12px;
  border: 1px solid #fbdccb;
  border-radius: 999px;
  background: var(--tint);
  color: var(--orange-dark);
  font-size: 13px;
  font-weight: 650;
}

.card {
  margin: 18px 0;
  padding: 24px 26px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--card);
  box-shadow: var(--shadow);
}

.card h2 {
  margin: 0 0 8px;
  font-size: 22px;
  line-height: 1.25;
  letter-spacing: -.015em;
}

.card h3 { margin: 22px 0 6px; font-size: 17px; }
.card p { margin: 8px 0; }
.card ul { margin: 10px 0 0; padding-left: 22px; }
.card li + li { margin-top: 7px; }

.contact {
  display: flex;
  align-items: flex-start;
  gap: 16px;
}

.contact-icon {
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  background: var(--tint);
  font-size: 22px;
}

.button {
  display: inline-block;
  margin-top: 12px;
  padding: 11px 17px;
  border-radius: 999px;
  background: var(--ink);
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  text-decoration: none;
}

.button:hover { color: #fff; opacity: .9; }

footer { border-top: 1px solid var(--line); color: var(--muted); }
.footer-inner { padding: 28px 0 42px; font-size: 14px; }
.footer-inner a { margin-right: 18px; }

@media (max-width: 560px) {
  .page { padding-top: 48px; }
  .card { padding: 21px 20px; }
  .contact { gap: 12px; }
}
